insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور رئيس محكمة استئناف نينوى','بحث الملفات ذات الصلة بالشأن القضائي والقانوني ودعم استقلال السلطة القضائية.','أجرى عضو لجنة النزاهة النيابية النائب راكان الشيخ صباح غازي الحنش، زيارة إلى رئيس محكمة استئناف نينوى القاضي رائد حميد مصلح، في لقاءٍ جرى خلاله بحث عدد من الملفات ذات الصلة بالشأن القضائي والقانوني، والتأكيد على أهمية دعم استقلال السلطة القضائية وترسيخ مبادئ العدالة وسيادة القانون.
insert into news (title,summary,content,image_url,category,published,published_at) values ('تهنئة بمناسبة ذكرى المولد النبوي الشريف','النائب راكان الحنش يهنئ أبناء الشعب العراقي والأمة الإسلامية بالمناسبة.','بمناسبة ذكرى المولد النبوي الشريف، نتقدّم بأسمى آيات التهاني والتبريكات إلى أبناء شعبنا العراقي الكريم، وإلى الأمة الإسلامية جمعاء، سائلين الله تعالى أن يعيد هذه المناسبة المباركة علينا بالخير واليُمن والبركات.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور الشيخ أنور أبو حسن شيخ عشيرة آل طربزون','زيارة إلى شيخ عشيرة آل طربزون من قبيلة الراشد – إمارة طي.','أجرى النائب راكان الشيخ صباح غازي الحنش، عضو لجنة النزاهة، زيارةً إلى الشيخ أنور أبو حسن، شيخ عشيرة آل طربزون من قبيلة الراشد – إمارة طي.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور وكيل وزارة الداخلية','بحث الملفات ذات الصلة بعمل الوزارة وتعزيز التنسيق والتعاون المشترك.','زار عضو لجنة النزاهة النائب راكان الشيخ صباح غازي الحنش، وكيل وزارة الداخلية الدكتور حسين العوادي، لبحث عدد من الملفات ذات الصلة بعمل الوزارة، ومناقشة سبل تعزيز التنسيق والتعاون المشترك، بما يسهم في دعم جهود وزارة الداخلية والارتقاء بمستوى الأداء الأمني والمؤسسي، خدمةً للمصلحة العامة وأبناء العراق.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور رئيس جمهورية العراق','بحث القضايا والملفات ذات الاهتمام الوطني وتعزيز التعاون بين مؤسسات الدولة.','أجرى عضو لجنة النزاهة النائب راكان الشيخ صباح غازي الحنش، زيارة إلى رئيس جمهورية العراق السيد نزار ئاميدي، جرى خلالها بحث عدد من القضايا والملفات ذات الاهتمام الوطني، وتبادل وجهات النظر بشأن مستجدات المشهد العراقي، والتأكيد على أهمية تعزيز التعاون والتنسيق بين مؤسسات الدولة، بما يدعم الاستقرار ويعزز مسيرة العمل الوطني ويخدم المصلحة العليا للعراق.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور محافظ نينوى برفقة وجهاء ناحية القراج','نقل مطالب الأهالي واحتياجاتهم مباشرة إلى المحافظ ومتابعتها ميدانياً.','ضمن متابعته المستمرة لاحتياجات أبناء نينوى، زار النائب راكان الشيخ صباح غازي الحنش، عضو لجنة النزاهة، محافظ نينوى الحقوقي عبد القادر الدخيل، برفقة عدد من شيوخ ووجهاء ناحية القراج، لنقل مطالب الأهالي واحتياجاتهم بشكل مباشر.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور وزير النفط برفقة النائب صلاح ياسين الكرغولي','بحث الملفات الاستراتيجية المرتبطة بقطاع النفط وتعزيز التنسيق المشترك.','أجرى عضو لجنة النزاهة النائب راكان الشيخ صباح غازي الحنش، برفقة النائب صلاح ياسين الكرغولي، زيارة إلى معالي وزير النفط المهندس باسم محمد خضير، جرى خلالها بحث عدد من الملفات الاستراتيجية المرتبطة بقطاع النفط، والتأكيد على أهمية استمرار التنسيق المشترك لدعم جهود الوزارة، وتعزيز كفاءة الأداء، بما يواكب متطلبات المرحلة ويخدم المصلحة العليا للعراق.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور وزير العدل','بحث الملفات المتعلقة بقطاع العدالة وتعزيز التعاون بين السلطتين التشريعية والتنفيذية.','أجرى عضو لجنة النزاهة النيابية النائب راكان الشيخ صباح غازي الحنش، زيارة إلى معالي وزير العدل الدكتور خالد شواني، جرى خلالها بحث عدد من الملفات المتعلقة بقطاع العدالة، ومناقشة سبل تعزيز التعاون والتنسيق بين السلطتين التشريعية والتنفيذية، بما يسهم في دعم مسيرة الإصلاح القانوني والإداري، وترسيخ مبادئ سيادة القانون والعدالة، والارتقاء بمستوى الخدمات التي تقدمها وزارة العدل للمواطنين، بما يحقق المصلحة العامة.
insert into news (title,summary,content,image_url,category,published,published_at) values ('المكتب يعلن رقماً مخصصاً لاستقبال الطلبات والشكاوى عبر واتساب','رقم رسمي لتقديم شكاوى وطلبات أهالي نينوى ومتابعتها مباشرة مع النائب.','إلى أهلنا الكرام في محافظة نينوى، لتسهيل تقديم شكواكم وطلباتكم الخدمية ومتابعتها مباشرة مع النائب راكان الشيخ صباح غازي الحنش عضو لجنة النزاهة، نعلن عن تخصيص الرقم 07779006161 لاستقبال اتصالاتكم ورسائلكم عبر الواتساب، ومتابعتها من قبل المكتب الإداري المختص وبإشراف مباشر من النائب، وإحالتها إلى الجهات المعنية ومتابعة إجراءاتها.
insert into news (title,summary,content,image_url,category,published,published_at) values ('وجبة جديدة من الموافقات والطلبات المنجزة لأهالي نينوى','المكتب يعلن إنجاز وجبة جديدة من معاملات المواطنين لدى الوزارات والدوائر الحكومية.','يعلن مكتب النائب راكان الشيخ صباح غازي الحنش لأهلنا في محافظة نينوى عن صدور وجبة جديدة من الموافقات والطلبات المنجزة، ضمن المتابعة المستمرة لملفات المواطنين لدى الوزارات والجهات الحكومية، بالتواصل المباشر والتنسيق مع الدوائر المختصة لتذليل العقبات وتسريع الإجراءات.
insert into news (title,summary,content,image_url,category,published,published_at) values ('إنجاز معاملات وزارات العمل والصحة والتربية والعدل والداخلية','وجبة جديدة تشمل الرعاية الاجتماعية والمعين المتفرغ وذوي الاحتياجات الخاصة.','أعلن مكتب النائب راكان الحنش عن صدور وجبة جديدة من الموافقات والطلبات المنجزة، شملت متابعات وزارات: العمل والشؤون الاجتماعية، الصحة، التربية، العدل، والداخلية.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يتبنّى مطالب عدد من الشرائح','استقبل طلبات رسمية وتعهّد بمتابعتها مع الجهات المختصة.','استجابةً للمطالب المشروعة لعدد من الشرائح، استقبل النائب راكان الحنش عدداً من الطلبات الرسمية، هي:
insert into news (title,summary,content,image_url,category,published,published_at) values ('وجبة موافقات جديدة لوزارة العمل والشؤون الاجتماعية','شمول ذوي الاحتياجات الخاصة وتسجيل المعين المتفرغ وتحويل الرعاية الاجتماعية وغيرها.','أعلن المكتب عن وجبة جديدة من موافقات وزارة العمل والشؤون الاجتماعية، وتشمل:
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور رئيس هيئة المساءلة والعدالة','بحث الملفات المرتبطة بعمل الهيئة وتعزيز التنسيق المشترك.','أجرى عضو لجنة النزاهة النائب راكان الشيخ صباح غازي الحنش زيارة إلى رئيس الهيئة الوطنية العليا للمساءلة والعدالة الدكتور جبار حردان سلمان، جرى خلالها بحث عدد من الملفات المرتبطة بعمل الهيئة، ومناقشة آليات تعزيز التنسيق المشترك بما يدعم تطبيق القانون ويرسخ مبادئ العدالة ويعزز الدور الرقابي في حماية مؤسسات الدولة والحفاظ على المال العام.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يبحث واقع الكهرباء مع مدير توزيع كهرباء الشمال','مناقشة التحديات التي تواجه قطاع التوزيع في نينوى والإسراع في معالجتها.','ضمن متابعته للملفات الخدمية في نينوى، أجرى النائب راكان الشيخ صباح غازي الحنش زيارة إلى مدير عام الشركة العامة لتوزيع كهرباء الشمال المهندس زيدان خلف خضر، وجرى نقاش موسع حول واقع منظومة الكهرباء في المحافظة وآليات معالجة أبرز التحديات التي تواجه قطاع التوزيع، مع التأكيد على الإسراع في الحلول التي تعزز استقرار الشبكة وترتقي بالخدمات المقدمة للمواطنين.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور مدير مكافحة إجرام نينوى','زيارة لبحث الملفات الأمنية ودعم الجهود المبذولة في مكافحة الجريمة.','زار عضو لجنة النزاهة النيابية النائب راكان الشيخ صباح غازي الحنش، مدير مكافحة إجرام نينوى العميد محمد طلال العبيدي، في زيارة جرى خلالها بحث عدد من الملفات الأمنية، والتأكيد على أهمية دعم الجهود المبذولة في مكافحة الجريمة وتعزيز أمن واستقرار المحافظة.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور مدير الأمن الوطني في نينوى','بحث الملفات المتعلقة بالواقع الأمني وتعزيز التنسيق بين الجهات المعنية.','زار عضو لجنة النزاهة النيابية النائب راكان الشيخ صباح غازي الحنش، مدير الأمن الوطني في نينوى العقيد محمد الصفار، حيث جرى بحث عدد من الملفات التي تتعلق بالواقع الأمني في المحافظة، والتأكيد على أهمية تعزيز التنسيق والتعاون بين الجهات المعنية، بما يسهم في دعم الاستقرار وحماية أمن المواطنين ومؤسسات الدولة.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يلتقي مدير قسم تربية الحدباء','مناقشة واقع القطاع التربوي ومتابعة احتياجات المؤسسات التعليمية.','زار عضو لجنة النزاهة النيابية النائب راكان الشيخ صباح غازي الحنش، مدير قسم تربية الحدباء الدكتور خالد حمادي الجبوري، حيث جرى بحث واقع القطاع التربوي في المنطقة، ومناقشة أبرز الملفات التي تخص المؤسسات التعليمية والكوادر التربوية، والتأكيد على أهمية متابعة الاحتياجات والمعوقات والعمل على معالجتها بما يسهم في الارتقاء بالعملية التربوية وتوفير بيئة تعليمية أفضل للطلبة.
insert into news (title,summary,content,image_url,category,published,published_at) values ('النائب راكان الحنش يزور قيادة شرطة محافظة نينوى','بحث الواقع الأمني والإداري وتعزيز التنسيق لحماية أمن المواطنين.','زار عضو لجنة النزاهة النيابية النائب راكان الشيخ صباح غازي الحنش، مدير إدارة قيادة شرطة محافظة نينوى العميد محمد مسلم غريب البياتي، حيث جرى بحث عدد من الملفات المتعلقة بالواقع الأمني والإداري في المحافظة، والتأكيد على أهمية تعزيز التنسيق والتعاون بين الجهات المعنية، بما يدعم استقرار المحافظة ويحافظ على أمن المواطنين ومؤسسات الدولة.
insert into news (title,summary,content,image_url,category,published,published_at) values ('راكان الحنش: سنعمل على النهوض بنينوى والدفاع عن حقوقها','لقاء مع قناة الموصلية الفضائية بعد فوزه في انتخابات مجلس النواب عن قائمة «نينوى لأهلها».','في لقاء مع قناة الموصلية الفضائية، أكّد النائب راكان الحنش، الفائز في الانتخابات البرلمانية عن قائمة «نينوى لأهلها»، أنه سيعمل على النهوض بالمحافظة والدفاع عن حقوقها وخدمة أهلها.
insert into news (title,summary,content,image_url,category,published,published_at) values ('اختيار راكان الحنش عضواً في لجنة النزاهة النيابية','صوّت مجلس النواب العراقي على اختياره عضواً في لجنة النزاهة النيابية.','صوّت مجلس النواب العراقي على اختيار النائب راكان صباح غازي الحنش عضواً في لجنة النزاهة النيابية، لتعزيز الرقابة ومكافحة الفساد.',null,'جلسات البرلمان',true,null);
