insert into achievements (title,description,image_url,category,year) values ('عضوية لجنة النزاهة النيابية','اختاره مجلس النواب عضواً في لجنة النزاهة النيابية للمساهمة في الرقابة ومكافحة الفساد.','/img/interview.jpg','العمل النيابي',null);
insert into achievements (title,description,image_url,category,year) values ('لقاءات وزيارات مع كبار المسؤولين','زيارات رسمية إلى رئيس جمهورية العراق ووزيري النفط والعدل ووكيل وزارة الداخلية ورئيس محكمة استئناف نينوى ومحافظ نينوى، لبحث ملفات تخص المحافظة والمصلحة العامة.','/img/news/ig-3961329574446594404-0.jpg','العمل النيابي',2026);
insert into achievements (title,description,image_url,category,year) values ('متابعة وإنجاز معاملات المواطنين لدى الوزارات','وجبات متتالية من الموافقات والمعاملات المنجزة لأهالي نينوى في وزارات العمل والشؤون الاجتماعية والصحة والتربية والعدل والداخلية (الرعاية الاجتماعية، المعين المتفرغ، ذوو الاحتياجات الخاصة وغيرها)، تُعلن أولاً بأول على القناة الرسمية في تلغرام.',null,'خدمة المواطنين',2026);
insert into achievements (title,description,image_url,category,year) values ('تبنّي مطالب الشرائح الوظيفية والأمنية','تبنّى مطالب خريجي قناة النخبة، وإعادة فتح منظومة الكودات، وإنصاف احتياط النجاح للدورة 72 لكليتي الشرطة، وغيرها.',null,'العمل النيابي',2026);
insert into achievements (title,description,image_url,category,year) values ('متابعة ميدانية للملفات الأمنية والخدمية','زيارات متواصلة لمديرية مكافحة الإجرام والأمن الوطني وقيادة شرطة نينوى لبحث الملفات الأمنية وتعزيز التنسيق، ولقاء مدير تربية الحدباء لمتابعة احتياجات القطاع التربوي.',null,'العمل الميداني',2026);
